import { expect, test, type Locator, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import path from 'node:path';

type Credentials = { readonly email: string; readonly password: string };
type EmailActivationFixture = {
  readonly emailActivation: {
    readonly preferenceUser: Credentials;
    readonly nonEssentialCategoryLabel: string;
    readonly essentialCategoryLabel: string;
  };
};

let cachedFixture: EmailActivationFixture | undefined;

function fixture(): EmailActivationFixture {
  cachedFixture ??= JSON.parse(
    readFileSync(path.join(process.cwd(), 'tests', 'e2e', '.auth', 'fixture.json'), 'utf8'),
  ) as EmailActivationFixture;
  return cachedFixture;
}

async function waitForHydrated(locator: Locator): Promise<void> {
  await locator.waitFor({ state: 'visible' });
  await locator.evaluate((element) => new Promise<void>((resolve) => {
    const tick = () => Object.keys(element).some((key) => key.startsWith('__react'))
      ? resolve()
      : requestAnimationFrame(tick);
    tick();
  }));
}

async function signIn(page: Page, credentials: Credentials): Promise<void> {
  await page.goto('/login');
  const submit = page.getByRole('button', { name: 'Logga in' });
  await waitForHydrated(submit);
  await page.getByLabel('E-post').fill(credentials.email);
  await page.getByLabel('Lösenord').fill(credentials.password);
  await submit.click();
  await expect(page).toHaveURL(/\/dashboard$/);
}

test.describe('Story 13.4 E-postinställningar — authenticated journey (ATDD RED)', () => {
  test.skip('[P0] a user can persist a non-essential email opt-out after the server admits synthetic sandbox delivery', async ({ page }) => {
    await signIn(page, fixture().emailActivation.preferenceUser);
    await page.goto('/settings/notifications');

    const category = fixture().emailActivation.nonEssentialCategoryLabel;
    const emailPreference = page.getByRole('switch', { name: `${category} e-post`, exact: true });
    await expect(emailPreference).toBeVisible();
    await expect(emailPreference).toBeChecked();
    await expect(emailPreference).toBeEnabled();

    const saved = page.waitForResponse((response) =>
      response.url().endsWith('/api/notifications/preferences')
      && response.request().method() === 'PUT'
      && response.ok(),
    );
    await emailPreference.uncheck();
    await saved;

    await expect(page.getByRole('status')).toContainText(/sparad/i);
    await page.reload();
    await expect(page.getByRole('switch', { name: `${category} e-post`, exact: true })).not.toBeChecked();
  });

  test.skip('[P1] an essential email category remains visibly required while a non-essential category is editable', async ({ page }) => {
    await signIn(page, fixture().emailActivation.preferenceUser);
    await page.goto('/settings/notifications');

    const essential = page.getByRole('switch', {
      name: `${fixture().emailActivation.essentialCategoryLabel} e-post`,
      exact: true,
    });
    const nonEssential = page.getByRole('switch', {
      name: `${fixture().emailActivation.nonEssentialCategoryLabel} e-post`,
      exact: true,
    });

    await expect(essential).toBeChecked();
    await expect(essential).toBeDisabled();
    await expect(page.getByText(/obligatorisk notis/i)).toBeVisible();
    await expect(nonEssential).toBeEnabled();
  });
});

import { expect, test } from '@playwright/test';
import { readFileSync } from 'node:fs';
import path from 'node:path';

type UnsubscribeFixture = {
  readonly emailActivation: {
    readonly unsubscribe: {
      readonly activeToken: string;
      readonly revokedToken: string;
      readonly unknownToken: string;
      readonly rateLimitedToken: string;
    };
  };
};

let cachedFixture: UnsubscribeFixture | undefined;

function fixture(): UnsubscribeFixture {
  cachedFixture ??= JSON.parse(
    readFileSync(path.join(process.cwd(), 'tests', 'e2e', '.auth', 'fixture.json'), 'utf8'),
  ) as UnsubscribeFixture;
  return cachedFixture;
}

test.describe('Story 13.4 Public unsubscribe capability (ATDD RED)', () => {
  test.skip('[P0] an anonymous recipient can unsubscribe through a valid scoped token without loading the authenticated shell', async ({ page }) => {
    await page.goto(`/unsubscribe/${fixture().emailActivation.unsubscribe.activeToken}`);

    await expect(page.getByRole('heading', { name: /e-postinställningar/i })).toBeVisible();
    await expect(page.getByRole('button', { name: /avregistrera/i })).toBeVisible();
    await expect(page.getByRole('navigation', { name: 'Huvudnavigation' })).toHaveCount(0);
    await expect(page.getByRole('link', { name: /logga in|dashboard|notiser/i })).toHaveCount(0);

    const completed = page.waitForResponse((response) =>
      response.url().includes('/unsubscribe/')
      && response.request().method() === 'POST'
      && response.ok(),
    );
    await page.getByRole('button', { name: /avregistrera/i }).click();
    await completed;

    await expect(page.getByRole('status')).toContainText(/avregistrerad/i);
    await expect(page.getByRole('button', { name: /återaktivera|prenumerera igen/i })).toBeVisible();
  });

  test.skip('[P1] unknown and revoked public tokens receive one uniform inactive response with no tenant or recipient disclosure', async ({ page }) => {
    for (const token of [
      fixture().emailActivation.unsubscribe.unknownToken,
      fixture().emailActivation.unsubscribe.revokedToken,
    ]) {
      await page.goto(`/unsubscribe/${token}`);
      await expect(page.getByRole('heading', { name: /länken är inte längre aktiv/i })).toBeVisible();
      await expect(page.getByText(/tenant|kund|mottagare|@/i)).toHaveCount(0);
      await expect(page.getByRole('navigation', { name: 'Huvudnavigation' })).toHaveCount(0);
    }
  });

  test.skip('[P1] a rate-limited anonymous token request gives retry guidance without exposing subscription data', async ({ page }) => {
    await page.goto(`/unsubscribe/${fixture().emailActivation.unsubscribe.rateLimitedToken}`);

    const limited = page.waitForResponse((response) =>
      response.url().includes('/unsubscribe/')
      && response.status() === 429,
    );
    await page.getByRole('button', { name: /avregistrera/i }).click();
    await limited;

    await expect(page.getByRole('alert')).toContainText(/för många försök.*försök igen senare/i);
    await expect(page.getByText(/tenant|kund|mottagare|@/i)).toHaveCount(0);
  });
});
